            .state
            .animating()
            .then(|| app.state.turn_started.map(|t| t.elapsed().as_millis() / FRAME.as_millis()).unwrap_or(0));
        if frame.is_some() && frame != drawn_frame {
            redraw = true;
        }
        if redraw {
            draw(terminal, app)?;
